anchors.apps/desktop/src/contrib/plugin-files.ts:
export interface PluginFolder {
    id: string;
    name: string;
    path: string;
}

export interface PluginFileEntry {
    name: string;
    path: string;
    isDirectory: boolean;
}

export type PluginFilesResult<T extends object = object> = ({
    ok: true;
} & T) | {
    ok: false;
    error: string;
    message: string;
};

export interface PluginFiles {
    readonly dataFolder: 'data';
    requestFolder: () => Promise<PluginFilesResult<{
        folder: PluginFolder | null;
    }>>;
    folders: () => Promise<PluginFolder[]>;
    release: (folderId: string) => Promise<boolean>;
    list: (folder: string, path?: string) => Promise<PluginFilesResult<{
        entries: PluginFileEntry[];
        truncated: boolean;
    }>>;
    stat: (folder: string, path: string) => Promise<PluginFilesResult<{
        exists: boolean;
        isDirectory?: boolean;
        mtimeMs?: number;
        size?: number;
    }>>;
    readText: (folder: string, path: string) => Promise<PluginFilesResult<{
        mtimeMs: number;
        size: number;
        text: string;
    }>>;
    readDataUrl: (folder: string, path: string) => Promise<PluginFilesResult<{
        url: string;
    }>>;
    writeText: (folder: string, path: string, text: string, options?: {
        exclusive?: boolean;
    }) => Promise<PluginFilesResult<{
        mtimeMs: number;
        path: string;
        size: number;
    }>>;
    rename: (folder: string, path: string, name: string) => Promise<PluginFilesResult<{
        path: string;
    }>>;
    trash: (folder: string, path: string) => Promise<PluginFilesResult>;
}

